    static string Rename(string text)
    {
        var result=(text??"").Replace("Arisi","Narasi");
        var before=new[]{"Arga","Dimas","Raka","Nara","Bu Nadia"};var after=new[]{"Aji","Denis","Billy","Ari","Pak Bambang"};
        for(int i=0;i<before.Length;i++)result=System.Text.RegularExpressions.Regex.Replace(result,"\\b"+before[i]+"\\b",after[i]);
        return result;
    }
